head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF05816.xml";
scwin.fr_SecuGrpId;
scwin.gBzProcsNo;
scwin.gAcptNo;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.gIsurCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    if (!scwin.fn_CheckForm()) return;
    var pSEG_TP_CD = $c.stf.getObjectValue(cmb_SEG_TP_CD);
    if ($c.stf.getObjectValue(cmb_SEG_TP_CD) == "") {
        pSEG_TP_CD = "A";
    }
    var url = "/SegmentChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listMngSegment&inputMessageId=SEG_CHG_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SEG_TP_CD=" + pSEG_TP_CD;
    url += "&CHG_DD=" + $c.stf.getObjectValue(edt_CHG_DD);
    dts_List_2.DataID = encodeURI(url);
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(edt_CHG_DD) == "") {
        $c.win.alert("[조회일자] 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    return true;
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_2.setValue("총 " + dts_List_2.getTotalRow() + "건");
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.btn_Search_2_onclick = function() {
    scwin.fn_Search();
};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top_2);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_CHG_DD.setValue(vCurDate);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewOffice(grd_List_2, "세그먼트 현황", "", 8, 0);
};
scwin.btn_New_onclick = async function() {
    await $c.frame.CreateFrame("ULDSTF05811", "/lstproc/ULDSTF05815.gfm", "세그먼트 변경신청서(작성용)", 0, 0, 840, 715, "window", 0, 0, false);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
